// from src/locales/ja/blog.ts. Body + FAQs for article 'rotate-flip-image-guide' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>横向きの写真は、画像トラブルの中でも特によくあるものです。スマホで撮った写真を開いたら地平線が縦になっていたり、スキャンした書類が逆さまに読めたりする経験はないでしょうか。</p>\n<p>そんなときに役立つのが、回転と反転という2つの操作です。回転は画像全体を指定した角度だけ回し、反転は左右または上下を鏡のようにひっくり返します。</p>\n<p>この記事では、2つの操作をわかりやすく解説します。どの角度を使えばいいのか、反転した自撮りをどう直すのか、写真が勝手に回ってしまう理由、角を切らずに傾きを直す方法まで、順番に紹介します。説明する操作はすべて、ブラウザで動く<a href=\"/ja/gazou-kaiten-hanten/\">画像回転・反転</a>でそのまま試せます。</p>\n<h2 id=\"what-rotation-and-flipping-do\">回転と反転はそれぞれ何をするのか</h2>\n<p>回転は、画像を中心を軸にして回す操作です。90度回すと縦と横が入れ替わるので、横長の写真が縦長になります。180度回すと、画像は完全に逆さまになります。</p>\n<p>反転は回転とは別物です。左右反転は画像を鏡のように左右で入れ替え、上下反転は上下で入れ替えます。</p>\n<p>2つの操作は組み合わせることもできます。写真を90度回してから左右反転すれば、横向きでさらに裏返しになっていたスキャン画像も直せます。</p>\n<p>どちらの操作も、色や明るさ、シャープさは変えません。変わるのはピクセルの位置だけで、それ以外は元の画像のままです。</p>\n<h2 id=\"why-photos-end-up-sideways\">写真が横向きになってしまう理由</h2>\n<p>スマホのカメラは、向きの情報をEXIFというデータとしてファイルの中に記録します。ピクセル自体を回すのではなく、「どう持って撮ったか」というメモを残す仕組みです。</p>\n<p>ところが、このメモを読むアプリと読まないアプリがあります。読まないアプリで開くと、写真は回転したまま表示されてしまいます。</p>\n<p>だからこそ、同じ画像でもギャラリーでは正しく見えて、申請フォームやチャット、古いビューアーでは横向きに見えることがあるのです。</p>\n<p>スキャナーも同じ問題を起こします。紙を逆さまに読み込むと、そのまま逆さまの画像になります。こちらには向きのメモがないので、自動では直りません。</p>\n<p>自撮りも原因のひとつです。フロントカメラは鏡のようなプレビューを見せるため、保存された画像が反転したままになっていることがあります。</p>\n<h2 id=\"rotation-angles-explained\">回転の角度を解説：90度・180度・細かい角度</h2>\n<p>90度は最もよく使う角度です。縦向きで撮った写真が横向きに表示されるときや、その逆のときに使います。</p>\n<p>180度は、完全に逆さまの画像を直す角度です。スキャンした書類や、スマホを逆さまに持って撮った写真、古いカメラで保存された画像などで起こります。</p>\n<p>細かい角度は、その中間のケースに使います。地平線が5度だけ傾いているような写真は、90度回すのではなく、数度だけ直すのが正解です。</p>\n<p>CompressMyPicのツールでは、マイナス180度からプラス180度まで細かく指定できます。回転に合わせてキャンバスも自動で広がるので、傾いた写真の角が切れる心配もありません。</p>\n<h2 id=\"flip-horizontal-vs-vertical\">左右反転と上下反転の違い</h2>\n<p>左右反転は、画像の左右を入れ替えます。文字が逆さまに読める自撮りや、分け目が反対側にある髪型を直すときに使います。</p>\n<p>上下反転は、画像の上下を入れ替えます。使う機会は少なめですが、特殊な位置に取り付けたカメラで逆さまに撮れた画像を直すときに役立ちます。</p>\n<p>反転は向きだけでなく、画像の意味も変えてしまう点に注意が必要です。反転した標識は文字が逆に読めますし、反転した地図は方角が逆になります。</p>\n<p>だから反転は、よく考えて使いましょう。向きだけが問題なら回転を先に使い、本当に鏡像になっているときだけ反転します。</p>\n<h2 id=\"exif-orientation-basics\">EXIFの向き情報：写真が勝手に回る理由</h2>\n<p>スマホやカメラで撮った写真には、必ずEXIFというメタデータが付いています。その中の1項目が、撮影時にカメラをどう持っていたかを記録しています。</p>\n<p>最近のギャラリーやブラウザはこの情報を読んで、正しい向きで表示してくれます。ところが古いソフトや一部の申請フォーム、SNSでは読まれないことがあります。</p>\n<p>そのため、スマホでは正しく見える写真が、他の場所では横向きに見えるのです。ピクセルが回っていたのではなく、向きのメモが無視されていただけです。</p>\n<p>編集ツールで回転させれば、この問題は根本から直ります。ピクセル自体が書き換わり、向きのメモもリセットされるので、どのビューアーでも正しく表示されます。</p>\n<h2 id=\"formats-and-quality\">対応形式と画質：ファイルはどうなるのか</h2>\n<p>回転・反転ツールは、JPG、PNG、WebP、HEIC、GIF、BMP、SVGに対応し、1ファイル最大20MBまで使えます。元の形式のまま保存することも、JPG・PNG・WebPに変えることもできます。</p>\n<p>90度や180度の回転は、ほとんどの形式でほぼ劣化しません。ピクセルを並べ替えるだけで、最初からエンコードし直すわけではないからです。</p>\n<p>細かい角度の回転は別で、新しいキャンバスに描き直す必要があります。ツールはきれいに処理しますが、JPGを低い画質で保存し直すと、少し柔らかくなることがあります。</p>\n<p>シャープさを重視するなら、PNGやWebPを選びましょう。スクリーンショットや文字入りの画像では特に違いが出ます。普通の写真なら、高画質のJPGで十分です。</p>\n<h2 id=\"batch-rotation\">たくさんの写真をまとめて回転する</h2>\n<p>1枚だけならすぐ直せますが、フォルダごと横向きだと大変です。ツールは一括回転に対応しており、同じ回転をキューに入れた全画像に一度に適用できます。</p>\n<p>旅行やイベントのあと、数十枚の写真が同じ向きで間違っているときに便利です。まとめてアップロードして角度を1つ選び、ZIPでまとめてダウンロードできます。</p>\n<p>一括処理は、問題が同じときに最も効果的です。半分が90度、半分が270度なら、2回に分けて処理しましょう。</p>\n<p>ZIPの中では、それぞれのファイルが元の名前のまま保存されます。1枚だけ必要なら、そのファイルだけダウンロードすることもできます。</p>\n<h2 id=\"straightening-tilted-photos\">傾いた写真を角を切らずにまっすぐにする</h2>\n<p>傾いた地平線は、わずかな回転の問題です。数度しかずれていなくても、風景や海の写真では目立ってしまいます。</p>\n<p>スライダーを少しずつ動かして、地平線が水平になるのを確認しましょう。1〜2度で十分なことが多く、プレビューで変化がすぐわかります。</p>\n<p>細かい角度で回すと、フレームの角に三角形のすき間ができます。ツールはキャンバスを広げて回転後の画像全体を収めるので、写真の一部が切れることはありません。</p>\n<p>すき間は、形式によって背景色か透明で埋められます。JPGでは単色になり、PNGでは透明のまま残ります。</p>\n<h2 id=\"fixing-mirrored-selfies\">反転した自撮りを直す</h2>\n<p>フロントカメラは、鏡と同じように反転したプレビューを見せます。機種によっては、その反転したままの画像が保存されることがあります。</p>\n<p>服の文字が逆さまに読める自撮りは、左右反転で直ります。1クリックで鏡像が元に戻り、文字も正しく読めるようになります。</p>\n<p>反転する前に、文字だけでなく画像全体を確認しましょう。ほくろや傷、髪の分け目も反対側に移動するので、写真の印象が変わります。</p>\n<p>プロフィール写真や証明写真では、反転していないバージョンが正解のことが多いです。鏡の中の自分ではなく、他の人から見た姿に近くなるからです。</p>\n<h2 id=\"rotate-vs-crop\">回転とトリミング、どちらを先にするか</h2>\n<p>回転とトリミングは別の問題を解決しますが、よく一緒に使います。まず回転で向きを直し、そのあとトリミングで構図を整えるのが基本です。</p>\n<p>トリミングのあとに回転すると、せっかくの作業が無駄になることがあります。横長用に切った構図が、回転で縦長になって合わなくなるからです。</p>\n<p>傾きを直してからトリミングするのも定番の組み合わせです。数度回して地平線を水平にし、そのあと回転でできた角のすき間を切り落とします。</p>\n<p>両方のツールが必要なら、回転のあとに<a href=\"/ja/gazou-torimingu/\">画像トリミングツール</a>を使いましょう。回転したピクセルはそのままに、選んだ端だけを切り取れます。</p>\n<h2 id=\"privacy-local-processing\">プライバシー：写真は自分の端末の中だけ</h2>\n<p>回転の処理は、すべてブラウザの中で行われます。写真がサーバーにアップロードされることはないので、個人の写真や医療関連、仕事の書類でも安心です。</p>\n<p>アップロードが必要なツールと比べると、これは大きな利点です。パスポートのスキャンや家族写真を、向きを直すためだけに見知らぬサーバーに送る必要はありません。</p>\n<p>ツールは書き出し時にEXIFの位置情報も取り除きます。回転してダウンロードした写真には、撮影場所の記録は残りません。</p>\n<p>身分証や申請書類のスキャンでは、この組み合わせが特に便利です。向きの修正と位置情報の削除を、1回の操作で済ませられます。</p>\n<h2 id=\"common-mistakes\">回転でよくある失敗</h2>\n<p>最も多い失敗は、逆方向に回してしまうことです。時計回りに90度必要な写真を反時計回りに回すと、さらに悪くなります。ダウンロード前にプレビューで確認しましょう。</p>\n<p>回転が必要なのに反転してしまう失敗もあります。横向きの写真を反転しても横向きのままで、かえって不自然な仕上がりになります。</p>\n<p>90度回すと縦と横が入れ替わることも忘れがちです。横長のバナー用に切った写真は、回転すると縦長になり、使いたい場所に合わなくなることがあります。</p>\n<p>最後に、同じJPGを何度も回転して保存しないことです。保存するたびに少しずつ劣化するので、必ず元のファイルから回転して、保存は1回だけにしましょう。</p>\n<h2 id=\"when-to-rotate-vs-reshoot\">回転で直すか、撮り直すか</h2>\n<p>回転は向きを直せますが、悪い写真を良くはできません。ピントがぼけた写真や、光が足りない写真は、何度回してもそのままです。</p>\n<p>被写体がぼけていたり、光が悪かったりするなら、撮り直すのが正解です。カメラが写し損ねたディテールは、どの角度の回転でも戻りません。</p>\n<p>写真自体は良いのに向きだけが間違っているときこそ、回転の出番です。良い画像をさっと直す、それがこのツールの役割です。</p>\n<p>書類も同じ考え方です。まっすぐで読みやすいスキャンは回転だけで十分ですが、斜めだったり影が入ったりしているものは、もう一度スキャンしたほうが早いでしょう。</p>\n<h2 id=\"rotating-scanned-receipts\">スキャンした領収書や書類を回転する</h2>\n<p>領収書や紙の書類は、急いでスキャンすると斜めや横向きになりがちです。横向きの領収書は読みにくく、整理もしにくくなります。</p>\n<p>記録として保存する前に、向きを直しておきましょう。90度回せば文字がまっすぐになり、少し斜めなら細かい角度で直せます。</p>\n<p>経費の記録では、回転させたあとにスキャナーの余白をトリミングすると、きれいで読みやすいファイルになります。経費申請に添付しやすくなります。</p>\n<p>回転のあとは、数字を確認しましょう。合計や日付がプレビューではっきり読めれば、ダウンロード版も大丈夫です。ぼやけているなら回転ではなく再スキャンが必要です。</p>\n<h2 id=\"rotation-and-printing\">印刷するときの回転</h2>\n<p>プリンターは画面の見た目ではなく、ピクセルそのものに従います。画面では正しく見える写真でも、EXIFのメモだけに頼っていると、印刷では横向きになることがあります。</p>\n<p>印刷に出す前に、必ず向きを直しておきましょう。ツールでピクセルを回転させ、修正したファイルをダウンロードして、その版で印刷します。</p>\n<p>90度回したあとは、寸法も確認が必要です。縦と横が入れ替わるので、横長の写真が縦長になり、用紙サイズも変える必要が出てきます。</p>\n<p>額装するプリントでは、まず回転してから額の比率に合わせてトリミングします。この順番なら構図が崩れず、被写体が切れる心配もありません。</p>\n<h2 id=\"rotation-file-naming\">回転したファイルの名前と整理</h2>\n<p>回転したファイルには、わかりやすい名前を付けましょう。beach-rotated.jpgのような名前ならあとで見つけやすく、IMG_4821.jpgでは何の写真かわかりません。</p>\n<p>元のファイルは別フォルダに保管しておきます。回転版は共有やアップロード用、元ファイルはやり直し用のバックアップという使い分けです。</p>\n<p>まとめて回転したときは、ZIPを解凍してイベント名やプロジェクト名のフォルダに入れます。整理されたフォルダがあれば、数か月後に1枚探すときもすぐ見つかります。</p>\n<p>回転版で元のファイルを上書きしないようにしましょう。元がなくなると、回転をやり直すことができず、JPGは保存するたびに劣化してしまいます。</p>\n<h2 id=\"combining-rotation-with-edits\">回転と他の編集を組み合わせる</h2>\n<p>回転は、長い編集の最初のステップになることが多いです。横向きの写真は、回転のほかにトリミングや明るさ調整、リサイズが必要な場合もあります。</p>\n<p>順番はシンプルに考えましょう。まず回転、次にトリミング、そのあと明るさやコントラストの調整です。順番を守ると、無駄な手戻りが減ります。</p>\n<p>回転のあと、暗い写真は明るさを調整したくなるかもしれません。横向きで撮った暗い写真は、まっすぐになっても暗いままです。<a href=\"/ja/gazou-akari-chosei/\">画像明るさ調整ツール</a>で直せます。</p>\n<p>回転した写真が大きすぎる場合は、<a href=\"/ja/gazou-saizu-henkou/\">画像リサイズツール</a>で小さくします。回転のあとにリサイズすれば、新しい向きに合った寸法になります。</p>\n<p>回転のあとに切り取りが必要なら、<a href=\"/ja/gazou-torimingu/\">画像トリミングツール</a>を使いましょう。手順の詳しい版は<a href=\"/ja/blog/gazou-kaiten-hanten-yarikata/\">画像を回転・反転させる方法</a>、向きの問題の深掘りは<a href=\"/ja/blog/shashin-no-muki-exif-kaisetsu/\">写真の向きとEXIF回転の問題を解説</a>をご覧ください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"回転と反転、どちらを使えばいいですか？","answer":"画像が横向きや逆さまなら回転を使います。反転は、文字が逆さまに読める自撮りのように、画像が鏡像になっているときだけ使います。横向きの写真を反転しても横向きのままなので、まず何が問題なのかを確認しましょう。"},{"question":"回転するとファイルサイズは大きくなりますか？","answer":"90度や180度の回転では、ほとんど変わりません。ピクセルを並べ替えるだけで、再エンコードしないからです。細かい角度の回転では、キャンバスが広がる分だけ少し変わることがありますが、通常は気にするほどではありません。"},{"question":"スマホでは正しく見えるのに、サイトでは横向きになるのはなぜですか？","answer":"ギャラリーはEXIFの向き情報を読んでいますが、そのサイトは読んでいないからです。ツールで回転させればピクセル自体が書き換わり、向きのメモもリセットされるので、その後はどこでも正しく表示されます。"},{"question":"横向きで逆さまのスキャン書類も直せますか？","answer":"はい、直せます。完全に逆さまなら180度、横向きなら90度回します。さらに鏡像になっている場合は、回転のあとに左右反転を加えます。各ステップのあとにプレビューで文字が正しく読めるか確認しましょう。"},{"question":"少しだけ傾いた地平線は何度で直せばいいですか？","answer":"1〜2度から始めて、プレビューを見ながら調整しましょう。傾いた地平線のほとんどは数度の修正で直ります。大きな角度は、明らかに横向きの写真用です。"},{"question":"回転すると位置情報は消えますか？","answer":"はい、回転・反転ツールから書き出すと、EXIFのGPS情報は取り除かれます。回転でピクセルが書き換わり、位置情報は引き継がれません。元のデータを残したい場合は、元ファイルを別に保管しておきましょう。"}];
